def pattern(n):
    if n <= 0:
        return ""

    def generate_line(i, max_length):
        line = ""
        for j in range(1, i + 1):
            line += str(j % 10)
        for j in range(i - 1, 0, -1):
            line += str(j % 10)
        return line.center(max_length)

    max_length = 2 * n - 1
    lines = []
    for i in range(1, n + 1):
        lines.append(generate_line(i, max_length))
    for i in range(n - 1, 0, -1):
        lines.append(generate_line(i, max_length))

    return "\n".join(lines)

